import { ProjectGroupRevisionAction } from '@/generated/graphql'
import { ChatBlockType, type Block } from '@/screens/project/chat/utils/types'
import { LLMTag } from '@/screens/project/chat/utils/llm-tags'

export type ModeKey =
	| 'auto'
	| 'discussion'
	| 'thinking'
	| 'fast'
	| 'max'
	| 'orchestrator'
	| 'debug'
	| 'sub-agent'

export type ModeMetadata = {
	label: string
	description: string
}

export const MODE_METADATA: Record<ModeKey, ModeMetadata> = {
	auto: {
		label: 'Auto',
		description: 'Chooses best mode for your task'
	},
	discussion: {
		label: 'Discussion',
		description: 'Chat without making changes'
	},
	thinking: {
		label: 'Thinking',
		description: 'Best for most tasks'
	},
	fast: {
		label: 'Fast',
		description: 'Fastest for simple tasks (less accurate)'
	},
	max: {
		label: 'MAX',
		description: 'Most capable for complex tasks'
	},
	orchestrator: {
		label: 'Orchestrator',
		description: 'Advanced agent that can delegate tasks to sub-agents'
	},
	debug: {
		label: 'Debug',
		description: 'Deep analysis for finding and fixing issues'
	},
	'sub-agent': {
		label: 'Sub-agent',
		description: 'Delegated to a specialized agent'
	}
}

export const ACTION_TO_MODE_KEY: Partial<
	Record<ProjectGroupRevisionAction, ModeKey>
> = {
	[ProjectGroupRevisionAction.DISCUSSION]: 'discussion',
	[ProjectGroupRevisionAction.CHAT]: 'thinking',
	[ProjectGroupRevisionAction.EXPERT_SWE]: 'max',
	[ProjectGroupRevisionAction.AUTO_SELECT_CHAT]: 'auto',
	[ProjectGroupRevisionAction.ORCHESTRATOR]: 'orchestrator',
	[ProjectGroupRevisionAction.DEEP_DEBUGGING]: 'debug',
	[ProjectGroupRevisionAction.DELEGATE_TO_SUB_AGENT]: 'sub-agent'
}

export const getModeKeyForAction = ({
	action,
	hasExtendedThinking
}: {
	action: ProjectGroupRevisionAction
	hasExtendedThinking: boolean
}): ModeKey | null => {
	if (action === ProjectGroupRevisionAction.CHAT && !hasExtendedThinking) {
		return 'fast'
	}
	return ACTION_TO_MODE_KEY[action] ?? null
}

export const hasExtendedThinkingBlock = (blocks: Block[]) =>
	blocks.some(
		(block) =>
			block.type === ChatBlockType.TAG &&
			block.tag === LLMTag.FILE_BASED_BLOCK &&
			block.args?.thinkingType === 'reasoning'
	)

export type PickerModeKey = 'fast' | 'discussion' | 'thinking' | 'max' | 'auto'

/**
 * Maps mode keys used in the mode picker to their corresponding actions.
 */
export const MODE_KEY_TO_ACTION: Record<
	PickerModeKey,
	{ action: ProjectGroupRevisionAction; isThinkingMode: boolean }
> = {
	fast: {
		action: ProjectGroupRevisionAction.CHAT,
		isThinkingMode: false
	},
	discussion: {
		action: ProjectGroupRevisionAction.DISCUSSION,
		isThinkingMode: true
	},
	thinking: {
		action: ProjectGroupRevisionAction.CHAT,
		isThinkingMode: true
	},
	max: {
		action: ProjectGroupRevisionAction.EXPERT_SWE,
		isThinkingMode: true
	},
	auto: {
		action: ProjectGroupRevisionAction.AUTO_SELECT_CHAT,
		isThinkingMode: false
	}
}
